export const ic = n => ICONS[n] || '';
// Điền icon cho mọi phần tử có data-ic="tên" trong root.
export function paintIcons(root = document) {
  root.querySelectorAll('[data-ic]').forEach(e => { if (!e.dataset.icOk) { e.innerHTML = ic(e.dataset.ic); e.dataset.icOk = '1'; } });
}
